// Detecta tipo de resposta e prepara dados para envio - VERSÃO CORRIGIDA
const agentOutput = $json.output || '';
const remoteJid = $('WhatsApp Webhook').first().json.body.event.Info.Sender;

// Detectar marcadores na resposta
const hasImage = agentOutput.includes('[IMAGEM:');
const hasAudio = agentOutput.includes('[AUDIO:');
const hasDocument = agentOutput.includes('[DOCUMENTO:');

// Extrair conteúdo dos marcadores - CORRIGIDO
let imageData = null;
let audioData = null;
let documentData = null;

if (hasImage) {
  // Regex mais simples e eficaz: captura tudo entre [IMAGEM: e ]
  const imageMatch = agentOutput.match(/\[IMAGEM:\s*([^\]]+)\]/i);
  if (imageMatch) {
    imageData = {
      prompt: imageMatch[1].trim(),
      needsGeneration: true
    };
  }
}

if (hasAudio) {
  // Regex mais simples e eficaz: captura tudo entre [AUDIO: e ]
  const audioMatch = agentOutput.match(/\[AUDIO:\s*([^\]]+)\]/i);
  if (audioMatch) {
    audioData = {
      text: audioMatch[1].trim(),
      needsGeneration: true
    };
  }
}

if (hasDocument) {
  // Melhorada para capturar metadata e conteúdo corretamente
  const docMatch = agentOutput.match(/\[DOCUMENTO:\s*([^\]]+)\]([\s\S]*?)(?=\[IMAGEM:|\[AUDIO:|\[DOCUMENTO:|$)/i);
  if (docMatch) {
    const metadata = docMatch[1].trim();
    const content = docMatch[2].trim();

    // Extract tipo and titulo from metadata
    const tipoMatch = metadata.match(/tipo=['"]([^'"]+)['"]|tipo=([^\s]+)/i);
    const tituloMatch = metadata.match(/titulo=['"]([^'"]+)['"]|titulo=([^\s]+)/i);

    documentData = {
      type: tipoMatch ? (tipoMatch[1] || tipoMatch[2]) : 'pdf',
      title: tituloMatch ? (tituloMatch[1] || tituloMatch[2]) : 'Documento',
      content: content,
      needsGeneration: true
    };
  }
}

// Limpar marcadores do texto - CORRIGIDO
let cleanText = agentOutput;

// Remove os marcadores de forma mais precisa
if (hasImage) {
  cleanText = cleanText.replace(/\[IMAGEM:\s*[^\]]+\]/gi, '');
}
if (hasAudio) {
  cleanText = cleanText.replace(/\[AUDIO:\s*[^\]]+\]/gi, '');
}
if (hasDocument) {
  cleanText = cleanText.replace(/\[DOCUMENTO:\s*[^\]]+\][\s\S]*?(?=\[IMAGEM:|\[AUDIO:|\[DOCUMENTO:|$)/gi, '');
}

// Limpa espaços extras e quebras de linha desnecessárias
cleanText = cleanText.replace(/\n\s*\n\s*\n/g, '\n\n').trim();

// Determinar tipo de resposta
let responseType = 'text';
const multimediaCount = [hasImage, hasAudio, hasDocument].filter(Boolean).length;

if (multimediaCount === 1) {
  if (hasImage) responseType = 'image';
  else if (hasAudio) responseType = 'audio';
  else if (hasDocument) responseType = 'document';
} else if (multimediaCount > 1) {
  responseType = 'multi';
}

// Validação final - garantir que os dados foram extraídos corretamente
const extractionSuccess = {
  image: hasImage ? imageData !== null : true,
  audio: hasAudio ? audioData !== null : true,
  document: hasDocument ? documentData !== null : true
};

const allExtractionsSuccessful = Object.values(extractionSuccess).every(success => success);

return {
  remoteJid: remoteJid,
  responseType: responseType,
  hasMultimedia: hasImage || hasAudio || hasDocument,
  textContent: cleanText,
  imageData: imageData,
  audioData: audioData,
  documentData: documentData,
  originalOutput: agentOutput,
  timestamp: new Date().toISOString(),
  // Dados de debug para ajudar no desenvolvimento
  debug: {
    detectionsFound: { hasImage, hasAudio, hasDocument },
    extractionSuccess: extractionSuccess,
    allExtractionsSuccessful: allExtractionsSuccessful,
    multimediaCount: multimediaCount
  }
};

// Multi-send handler - envia texto primeiro, depois mídia
const data = $json;
const outputs = [];

// Sempre enviar texto primeiro se houver
if (data.textContent) {
  outputs.push({
    type: 'text',
    remoteJid: data.remoteJid,
    content: data.textContent
  });
}

// Adicionar imagem se houver
if (data.imageData) {
  outputs.push({
    type: 'image',
    remoteJid: data.remoteJid,
    imageData: data.imageData
  });
}

// Adicionar áudio se houver
if (data.audioData) {
  outputs.push({
    type: 'audio',
    remoteJid: data.remoteJid,
    audioData: data.audioData
  });
}

// Adicionar documento se houver
if (data.documentData) {
  outputs.push({
    type: 'document',
    remoteJid: data.remoteJid,
    documentData: data.documentData
  });
}

return outputs;

